/bin/zsh -lc "bun --check /tmp/timezone-overlap-check/main.js && node --input-type=module - <<'NODE'
import fs from 'node:fs';
const pkg = JSON.parse(fs.readFileSync('package.json', 'utf8'));
const html = fs.readFileSync('index.html', 'utf8');
const app = fs.readFileSync('src/App.jsx', 'utf8');
const css = fs.readFileSync('src/styles.css', 'utf8');
const cityCatalog = app.slice(app.indexOf('const CITIES'), app.indexOf('const DEFAULTS'));
const cityCount = (cityCatalog.match(/\\{ id: '/g) || []).length;
const checks = [
  ['dev script uses 9139', pkg.scripts.dev.includes('--port 9139')],
  ['React/Vite dependencies present', Boolean(pkg.dependencies.react && pkg.dependencies['react-dom'] && pkg.dependencies.vite)],
  ['title is model name', html.includes('<title>GPT-5.6 Luna</title>')],
  ['heading is model name', app.includes('<h1>GPT-5.6 <span className=\"accent-word\">Luna</span></h1>')],
  ['catalog has 34 cities', cityCount === 34],
  ['localStorage persistence exists', app.includes('localStorage.setItem') && app.includes('localStorage.getItem')],
  ['DST-aware Intl offset math exists', app.includes('Intl.DateTimeFormat') && app.includes('timeZone')],
  ['fractional zones included', app.includes('Asia/Kolkata') && app.includes('Asia/Kathmandu')],
  ['separate mobile layout exists', css.includes('.desktop-grid-wrap { display: none; }') && css.includes('.mobile-grid-wrap { display: block;')],
  ['no raw http server or vanilla script', "'!app.includes('"'http.createServer') && "'!html.includes('"'<script>')],
];
for (const [name, ok] of checks) console.log("'`${ok ? '"'PASS' : 'FAIL'}  "'${name}`);
if (checks.some(([, ok]) => !ok)) process.exit(1);
NODE
printf '"'\\n--- status ---\\n'; git status --short 2>/dev/null || true"

