/bin/zsh -lc "node - <<'NODE'
const zones = ['America/Los_Angeles', 'Asia/Kolkata', 'Asia/Kathmandu'];
const date = new Date();
for (const timeZone of zones) {
  const parts = new Intl.DateTimeFormat('en-US', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23' }).formatToParts(date).reduce((a, p) => (p.type "'!== '"'literal' && (a[p.type] = p.value), a), {});
  const asUtc = Date.UTC(+parts.year, +parts.month - 1, +parts.day, +parts.hour, +parts.minute, +parts.second);
  console.log("'`${timeZone}: ${Math.round((asUtc - date.getTime()) / 60000)} minutes`);
}
NODE'

